/**
 * Sounds bundled with the app, generated by scripts/audio-pack (npm run audio:build):
 * the book's bell and silences of fixed lengths.
 */
import { SILENCE_SECONDS } from './sound-lengths';

export { BELL_SECONDS } from './sound-lengths';

export const BELL = require('@/assets/sounds/cloche.m4a') as number;

const SILENCES: Record<(typeof SILENCE_SECONDS)[number], number> = {
  600: require('@/assets/sounds/silence-600.m4a'),
  120: require('@/assets/sounds/silence-120.m4a'),
  30: require('@/assets/sounds/silence-30.m4a'),
  5: require('@/assets/sounds/silence-5.m4a'),
  1: require('@/assets/sounds/silence-1.m4a'),
};

/** Splits a silence into bundled files, longest first: 754 s → 600 + 120 + 30 + 1 + 1 + 1 + 1. */
export function silenceFiles(seconds: number): { module: number; seconds: number }[] {
  const out: { module: number; seconds: number }[] = [];
  let left = Math.max(0, Math.round(seconds));
  for (const length of SILENCE_SECONDS) {
    while (left >= length) {
      out.push({ module: SILENCES[length], seconds: length });
      left -= length;
    }
  }
  return out;
}
